using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using System.Web.Script.Serialization;class IncidentTest{
static Frame Sample(string peer,bool lost){var f=new Frame{Devices=new Dictionary<string,Observation>()};foreach(var key in new[]{"mini","other","stable"}){if(lost&&key=="other")continue;var o=new Observation{Name=key,State=peer};o.Local.Add(new Segment{Id=key+"|"+(key=="mini"?peer:"450E")+"|port"});f.Devices[key]=o;}return f;}
[STAThread]static void Main(string[] args){var old=Sample("450E",false);var next=Sample("6000",true);if(IncidentReading.Parent(next,"mini")!="6000"||!IncidentReading.Compare(old,next,"450E","mini").Contains("1 weiterhin zugeordnet · nicht mehr dort: other"))throw new Exception("Vergleich");using(var a=new Atlas()){var flags=BindingFlags.NonPublic|BindingFlags.Instance;var type=typeof(Atlas);type.GetField("archive",flags).SetValue(a,args[0]);var marker=new Frame{Kind="mark",Marker="m",Message="Test"};type.GetMethod("Save",flags).Invoke(a,new object[]{marker});var task=(Task)type.GetMethod("CaptureIncident",flags).Invoke(a,new object[]{marker,"mini","Mini"});while(!task.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(5);}task.GetAwaiter().GetResult();type.GetMethod("LoadDay",flags).Invoke(a,null);var plot=(HistoryPlot)type.GetField("plot",flags).GetValue(a);var record=plot.Frames.Single(f=>f.Kind=="incident");if(record.Marker!="m"||!record.Incident.Report.Contains("Routerabfrage fehlgeschlagen")||record.Incident.Mesh!=null)throw new Exception("Fehlerzustand");}Console.WriteLine("OK");}}